const metricsRaw = $('query_metrics').first().json;
const metrics = metricsRaw.metrics || metricsRaw;

const samples = $('query_conversation_samples').all();

// Group by session_id
const grouped = {};
for (const row of samples) {
  const sid = row.json.session_id;
  if (!grouped[sid]) {
    grouped[sid] = { type: row.json.session_type, messages: [] };
  }
  grouped[sid].messages.push({
    role: row.json.role,
    content: row.json.content
  });
}

// Build conversation text
let conversationsText = '';
for (const [sid, data] of Object.entries(grouped)) {
  conversationsText += `\n--- Sesión: ${sid} (${data.type}) ---\n`;
  for (const msg of data.messages) {
    const prefix = msg.role === 'human' ? 'USUARIO' : 'BOT';
    conversationsText += `[${prefix}]: ${msg.content}\n`;
  }
}

const reportDate = DateTime.now().setZone('America/Bogota').toFormat('dd/MM/yyyy');

return [{
  json: {
    metrics_summary: JSON.stringify(metrics, null, 2),
    conversations_text: conversationsText,
    report_date: reportDate
  }
}];

