parameters.jsCode:
const llmOutput = $('llm_analysis').first().json.output || $('llm_analysis').first().json.text || '';
const reportDate = $('build_analysis_payload').first().json.report_date;
const metrics = JSON.parse($('build_analysis_payload').first().json.metrics_summary);

// Simple markdown to HTML
let htmlBody = llmOutput
  .replace(/## (.*)/g, '<h2 style="color:#1a1a2e;margin-top:24px;margin-bottom:8px;font-size:18px;">$1</h2>')
  .replace(/### (.*)/g, '<h3 style="color:#16213e;margin-top:16px;margin-bottom:6px;font-size:15px;">$1</h3>')
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
  .replace(/^- (.*)/gm, '<li style="margin-bottom:4px;">$1</li>')
  .replace(/(<li.*<\/li>\n?)+/g, '<ul style="padding-left:20px;margin:8px 0;">$&</ul>')
  .replace(/\n\n/g, '<br><br>')
  .replace(/\n/g, '<br>');

const totalSessions = metrics.total_sessions || 'N/A';
const totalMessages = metrics.total_messages || 'N/A';
const sessions7d = metrics.sessions_last_7d || 'N/A';
const messages7d = metrics.messages_last_7d || 'N/A';

const html = `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"></head>
<body style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;max-width:700px;margin:0 auto;background:#f5f5f5;padding:20px;">
  <div style="background:#1a1a2e;color:white;padding:24px;border-radius:8px 8px 0 0;text-align:center;">
    <h1 style="margin:0;font-size:22px;">GymBot — Análisis Semanal</h1>
    <p style="margin:8px 0 0;opacity:0.8;font-size:14px;">${reportDate}</p>
  </div>
  <div style="background:white;padding:24px;border-radius:0 0 8px 8px;">
    <table style="width:100%;border-collapse:collapse;margin-bottom:24px;">
      <tr style="background:#f0f0f0;">
        <td style="padding:12px;text-align:center;border:1px solid #ddd;"><strong>Sesiones Totales</strong><br><span style="font-size:24px;color:#1a1a2e;">${totalSessions}</span></td>
        <td style="padding:12px;text-align:center;border:1px solid #ddd;"><strong>Mensajes Totales</strong><br><span style="font-size:24px;color:#1a1a2e;">${totalMessages}</span></td>
      </tr>
      <tr style="background:#f8f8f8;">
        <td style="padding:12px;text-align:center;border:1px solid #ddd;"><strong>Sesiones (7d)</strong><br><span style="font-size:24px;color:#e94560;">${sessions7d}</span></td>
        <td style="padding:12px;text-align:center;border:1px solid #ddd;"><strong>Mensajes (7d)</strong><br><span style="font-size:24px;color:#e94560;">${messages7d}</span></td>
      </tr>
    </table>
    ${htmlBody}
  </div>
  <p style="text-align:center;color:#888;font-size:12px;margin-top:16px;">Generado automáticamente por GymBot Interaction Analysis</p>
</body>
</html>`;

return [{
  json: {
    html: html,
    subject: 'GymBot Análisis Semanal - ' + reportDate,
    to: 'camilodiazjaimes@gmail.com'
  }
}];
